import { BadRequestError } from './BadRequestError';

type Fields = Record<string, unknown>;

export function asFields(source: unknown): Fields {
  if (source === undefined || source === null) {
    return {};
  }
  if (typeof source !== 'object' || Array.isArray(source)) {
    throw new BadRequestError('Request body must be a JSON object');
  }
  return source as Fields;
}

export function optionalString(fields: Fields, name: string): string | undefined {
  const value = fields[name];
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== 'string') {
    throw new BadRequestError(`'${name}' must be a string`);
  }
  return value;
}

export function requiredString(fields: Fields, name: string): string {
  const value = optionalString(fields, name);
  if (value === undefined) {
    throw new BadRequestError(`'${name}' is required`);
  }
  return value;
}

=====SOURCE-END=====

